fn test_list_jobs_request_with_count_and_cursor() {
    let json = r#"{"count":5,"cursor":"eyJjcmVhdGVkX2F0IjoiMjAyNS0wNi0xNVQxMDozMDowMFoiLCJpZCI6IjU1MGU4NDAtZTI5Yi00MWQ0LWE3MTYtNDQ2NjU1NDQwMDAwIn0"}"#;
